      <view v-else-if="activeTab === 'carbon'" class="carbon-tab"><view class="carbon-title"><text>CARBON ASSETS</text><b>碳资产</b></view><view class="carbon-hero"><view class="orbit">◌</view><view class="hero-head"><view><text>CARBON ASSETS</text><b>我的碳资产</b></view><em>♧</em></view><view class="carbon-stats"><view><text>✦</text><b>8,620</b><small>pts</small><i>总碳积分</i></view><view><text>◉</text><b>247</b><small>km</small><i>骑行里程</i></view><view><text>♧</text><b>12</b><small>棵</small><i>等效植树</i></view></view><view class="eco-tip">☀ 本月减排相当于驾车少行驶 <b>186 km</b></view></view><view class="wallet"><view><text>碳积分钱包</text><b>8,620 pts</b></view><button @click="toast('积分明细加载中')">查看明细 ›</button></view><view class="section-label">碳积分商城</view><scroll-view class="mall" scroll-x :show-scrollbar="false"><view v-for="item in mallItems" :key="item.id" class="mall-item"><view :style="{ color: item.color, background: item.color + '18' }">{{ item.icon }}</view><b>{{ item.name }}</b><text>{{ item.desc }}</text><em>{{ item.pts }} pts</em><button :disabled="redeemed.includes(item.id)" @click="toggleRedeem(item.id)">{{ redeemed.includes(item.id) ? '已兑换' : '兑换' }}</button></view></scroll-view><view class="section-label">骑行记录</view><view class="records"><view v-for="record in records" :key="record.date" class="record"><view><b>{{ record.date }}</b><text>{{ record.time }} · {{ record.route }}</text></view><view><b>{{ record.km }} km</b><text>{{ record.pts }} pts · {{ record.carbon }}</text></view></view></view><view class="section-label">成就徽章</view><view class="badges"><view v-for="badge in badges" :key="badge.label" :class="{ locked: !badge.on }"><b>{{ badge.icon }}</b><text>{{ badge.label }}</text><small>{{ badge.desc }}</small></view></view></view>

      <view v-else-if="activeTab === 'community'" class="community-tab"><view class="community-head"><view><text>GREEN COMMUNITY</text><b>绿色社区</b></view><button @click="toast('发布功能即将开放')">＋ 发布</button></view><scroll-view class="community-nav" scroll-x :show-scrollbar="false"><text v-for="item in [{ id: 'recommended', label: '推荐' }, { id: 'following', label: '关注' }, { id: 'challenge', label: '话题挑战' }, { id: 'video', label: '科普视频' }]" :key="item.id" :class="{ active: carbonSubTab === item.id }" @click="carbonSubTab = item.id">{{ item.label }}</text></scroll-view><view v-if="carbonSubTab === 'challenge'" class="challenge"><view><b>🌿 本周骑行打卡挑战</b><text>完成5次骑行 · 赢双倍碳积分奖励</text></view><button @click="toast('已报名打卡挑战')">去参与</button></view><view v-if="carbonSubTab === 'video'" class="videos"><view v-for="item in ['5分钟了解碳中和', '电助力 vs 燃油车：谁更省钱', '城市骑行安全指南']" :key="item"><view>▶</view><b>{{ item }}</b><text>科普视频 · 4.2万观看</text></view></view><view v-else-if="!showPosts.length" class="empty">还没有关注的骑友，去推荐页看看吧</view><view v-else class="posts"><view v-for="post in showPosts" :key="post.id" class="post"><view class="post-user"><i :style="{ background: post.color }">{{ post.avatar }}</i><view><b>{{ post.user }}</b><text>{{ post.time }}</text></view><button @click="toggleFollow(post.id)">{{ followedPosts.includes(post.id) ? '✓ 已关注' : '+ 关注' }}</button></view><view class="post-body">{{ post.content }}</view><view class="post-photo" :style="{ background: `linear-gradient(135deg, ${post.color}, #c6e7ce)` }">低碳 · 骑行日记</view><view class="tags"><text v-for="tag in post.tags" :key="tag">{{ tag }}</text></view><view class="post-actions"><text @click="toggleLike(post)">{{ likedPosts.includes(post.id) ? '♥' : '♡' }} {{ post.likes }}</text><text @click="toast('评论功能即将开放')">◌ {{ post.comments }}</text><text @click="toast('已收藏')">⌑ 收藏</text></view></view></view></view>

      <view v-else class="profile-tab"><view class="profile-hero"><view class="profile-orbit">◌</view><view class="profile-top"><view class="avatar">林</view><view><b>林小绿</b><text>途能ID: TN-20240725</text><em><Star :size="10" fill="#5a3a00" /> 黄金骑士</em></view><button @click="toast('会员权益')"><Sparkles :size="13" /> 会员权益 <ChevronRight :size="12" /></button></view><view class="profile-stats"><view><b>247</b><text>km</text><small>累计里程</small></view><view><b>8,620</b><text>pts</text><small>碳积分</small></view><view><b>12</b><text>棵</text><small>等效植树</small></view></view></view><view class="profile-quick"><view v-for="item in [{ label: '我的订单', id: 'orders' }, { label: '碳积分钱包', id: 'wallet' }, { label: '我的车辆', id: 'vehicle' }, { label: '我的收藏', id: 'favorites' }]" :key="item.id" @click="openPanel(item.id)"><b><Package v-if="item.id === 'orders'" :size="22" /><Wallet v-else-if="item.id === 'wallet'" :size="22" /><Bike v-else-if="item.id === 'vehicle'" :size="22" /><Bookmark v-else :size="22" /></b><text>{{ item.label }}</text></view></view><view class="profile-group"><small>业务服务</small><view v-for="item in [{ title: '在线报修', desc: '快速提交故障申请', id: 'repair' }, { title: '智能客服', desc: '7×24小时智能响应', id: 'service' }, { title: '骑行记录', desc: '查看全部出行数据', id: 'rides' }]" :key="item.id" @click="openPanel(item.id)"><b><Wrench v-if="item.id === 'repair'" :size="19" /><MessageCircle v-else-if="item.id === 'service'" :size="19" /><Navigation v-else :size="19" /></b><view><strong>{{ item.title }}</strong><text>{{ item.desc }}</text></view><em><ChevronRight :size="18" /></em></view></view><view class="profile-group"><small>通用设置</small><view v-for="item in [{ title: '地址管理', desc: '常用地点与停车点', icon: 'address' }, { title: '隐私设置', desc: '数据授权与权限管理', icon: 'privacy' }, { title: '关于途能', desc: 'v2.4.1 · 检查更新', icon: 'about' }]" :key="item.title" @click="toast(item.title)"><b><MapPin v-if="item.icon === 'address'" :size="19" /><CircleHelp v-else-if="item.icon === 'privacy'" :size="19" /><Leaf v-else :size="19" /></b><view><strong>{{ item.title }}</strong><text>{{ item.desc }}</text></view><em><ChevronRight :size="18" /></em></view></view></view>
